import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.Boholvbs.js";const r="/docs/assets/minimap-block-edit.UnD4Jd-7.png",i="/docs/assets/minimap-block-edit2.o4RGJqBW.png",s="/docs/assets/minimap-block-edit3.B8iAsuLp.png",l="/docs/assets/minimap-understand-layers.Dko6JxjU.png",b=JSON.parse('{"title":"Minimap — AI-Assisted Map Block","description":"","frontmatter":{},"headers":[],"relativePath":"minimap/index.md","filePath":"minimap.md"}'),c={name:"minimap/index.md"};function h(d,e,p,m,g,u){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="minimap-—-ai-assisted-map-block" tabindex="-1">Minimap — AI-Assisted Map Block <a class="header-anchor" href="#minimap-—-ai-assisted-map-block" aria-label="Permalink to &quot;Minimap — AI-Assisted Map Block&quot;">​</a></h1><p>The Minimap block (<code>jeo/ai-minimap</code>) generates contextual interactive maps inside the Gutenberg editor using AI. Describe what you need in natural language, and the AI builds a map with appropriate layers, center point, zoom level, and geolocation pins.</p><p>See <a href="/docs/ai-in-jeo/">AI in JEO</a> to learn how RAG, agents, and tools power this feature.</p><h2 id="inserting-the-block" tabindex="-1">Inserting the block <a class="header-anchor" href="#inserting-the-block" aria-label="Permalink to &quot;Inserting the block&quot;">​</a></h2><ol><li>In the Gutenberg editor, click the <strong>+</strong> button to add a new block.</li><li>Search for <strong>JEO AI Minimap</strong> and select it.</li><li>The block starts in <strong>idle</strong> state with two generation modes: <ul><li><strong>From post content</strong>: Automatically generates a map based on the current post&#39;s content and geolocation points.</li><li><strong>From prompt</strong>: Describe the map you want in a text field.</li></ul></li></ol><p><img src="'+r+'" alt="Minimap block"></p><h2 id="generating-a-map" tabindex="-1">Generating a map <a class="header-anchor" href="#generating-a-map" aria-label="Permalink to &quot;Generating a map&quot;">​</a></h2><h3 id="from-post-content" tabindex="-1">From post content <a class="header-anchor" href="#from-post-content" aria-label="Permalink to &quot;From post content&quot;">​</a></h3><p>Click <strong>Generate from content</strong>. The system searches your existing layers and post geolocation data to build a contextual map. No AI prompt is needed — it uses RAG (Retrieval-Augmented Generation) to find relevant layers automatically.</p><h3 id="from-prompt" tabindex="-1">From prompt <a class="header-anchor" href="#from-prompt" aria-label="Permalink to &quot;From prompt&quot;">​</a></h3><p>Type a description of the map you want (e.g., &quot;A map of the Amazon region showing deforestation data and rivers&quot;) and click <strong>Generate</strong>. The AI agent will:</p><ol><li>Analyze your prompt and the current post content.</li><li>Search for relevant existing layers in your Knowledge Base.</li><li>Geocode relevant locations.</li><li>Return a complete map with layers, center, zoom, and pins.</li></ol><p><img src="'+i+'" alt="Minimap block"></p><h2 id="chat-refinement" tabindex="-1">Chat refinement <a class="header-anchor" href="#chat-refinement" aria-label="Permalink to &quot;Chat refinement&quot;">​</a></h2><p>Once a map is generated, the block enters <strong>ready</strong> state. An <strong>Inspector Panel</strong> opens in the Gutenberg sidebar where you can refine the map through chat:</p><ul><li><strong>Text messages</strong>: Type instructions like &quot;Zoom in on São Paulo&quot; or &quot;Remove the water layer&quot;.</li><li><strong>Regenerate</strong>: Start fresh with a completely new map suggestion.</li><li><strong>New prompt</strong>: Enter a new description to generate a different map (keeps the conversation context).</li><li><strong>Base layer variant</strong>: Switch between dark, light, and satellite base layers.</li></ul><p>The AI remembers your conversation, so each refinement builds on the previous context.</p><p><img src="'+s+'" alt="Minimap block chat"></p><h2 id="understanding-the-chosen-layers" tabindex="-1">Understanding the chosen layers <a class="header-anchor" href="#understanding-the-chosen-layers" aria-label="Permalink to &quot;Understanding the chosen layers&quot;">​</a></h2><p>Ever wondered why the AI picked a specific layer? Below the map preview, click <strong>Understand chosen layers</strong> to open the <strong>Map layers</strong> panel in the block sidebar. For each layer, you&#39;ll see:</p><ul><li><strong>Title and type</strong> — e.g. &quot;Deforestation alerts — mapbox&quot;.</li><li><strong>Description</strong> — the layer&#39;s excerpt, when available.</li><li><strong>Why it was chosen</strong> — the AI&#39;s own explanation for including the layer in this map.</li><li><strong>Automatic style notice</strong> — when the AI had to style a layer that had no saved style, so you know it can be customized.</li><li><strong>Themes and source</strong> — the layer&#39;s themes and data attribution, for disambiguation when similarly named layers exist.</li></ul><p><img src="'+l+'" alt="Understand chosen layers"></p><h2 id="ai-generated-layers-minilayer" tabindex="-1">AI-generated layers (Minilayer) <a class="header-anchor" href="#ai-generated-layers-minilayer" aria-label="Permalink to &quot;AI-generated layers (Minilayer)&quot;">​</a></h2><p>If you have a Mapbox API key configured, the AI can <strong>generate custom map layers</strong> when existing layers don&#39;t cover what you need. During chat, ask the AI to create a layer (e.g., &quot;Can you generate a deforestation heatmap for the Amazon?&quot;). The AI will ask for your confirmation before generating — it never creates layers without explicit approval. The new layer is added to the map automatically with AI-suggested styling (colors and filters) that you can later override in the layer settings modal via the <strong>&quot;Use AI Default Style&quot;</strong> checkbox.</p><h2 id="map-features" tabindex="-1">Map features <a class="header-anchor" href="#map-features" aria-label="Permalink to &quot;Map features&quot;">​</a></h2><p>After generation, the minimap behaves like any JEO map:</p><ul><li><strong>Pan and zoom</strong>: Drag to pan, scroll to zoom.</li><li><strong>Layers</strong>: Thematic layers with legends.</li><li><strong>Pins</strong>: Geolocation pins from the post&#39;s geolocation data. Use the <strong>Geolocation Pins</strong> panel (Show pins: Yes/No) to control them — they render live in the editor preview and on the frontend.</li><li><strong>Base layer</strong>: Automatically chosen (dark/light) based on layer colors, or manually selected.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An AI provider must be configured in <strong>Jeo → AI</strong> (see <a href="/docs/ai-settings/">AI Settings</a>).</li><li>For best results, index your posts and layers in the Knowledge Base (RAG tab).</li><li>For AI-generated thematic layers, a Mapbox API key is also required. Boundary layers (municipalities, states, indigenous lands) are generated as GeoJSON and work without a Mapbox key.</li></ul>',29)])])}const f=t(c,[["render",h]]);export{b as __pageData,f as default};
